# =============================================================================
# CONFIGURATION
# =============================================================================

@dataclass
class ProductionConfig:
    """Production configuration."""
    # Mode
    mode: RunMode = RunMode.PAPER
    
    # Timing
    master_tick_seconds: int = 14400  # 4H = 14400 seconds
    execution_loop_ms: int = 200       # Reserved: PA executor reprice interval (not polled by main loop)
    
    # Assets (v3.3-HR: SOL primary)
    assets: List[str] = field(default_factory=lambda: ["SOL", "BTC", "ETH"])
    primary_asset: str = "SOL"
    
    # Risk (v3.3-HR philosophy) -overridable via --risk-profile
    # [CFG-3] Defaults from canonical_config.py (single source of truth)
    risk_profile: str = "HIGH_RISK"
    hard_drawdown_halt: float = HARD_DRAWDOWN_HALT
    correlation_crisis: float = CORRELATION_CRISIS
    max_gross_exposure: float = MAX_GROSS_EXPOSURE
    max_single_asset_pct: float = MAX_SINGLE_ASSET_PCT
    max_leverage: float = MAX_LEVERAGE
    reduce_at_drawdown: float = REDUCE_AT_DRAWDOWN
    critical_drawdown: float = CRITICAL_DRAWDOWN
    # Leverage guard overrides
    max_position_notional_usd: float = MAX_POSITION_NOTIONAL_USD
    max_total_notional_usd: float = MAX_TOTAL_NOTIONAL_USD
    # Per-asset exposure caps (pre-leverage and post-leverage)
