    @staticmethod
    def _direction_to_trade_side(direction: float) -> str:
        if direction > 0:
            return "long"
        if direction < 0:
            return "short"
        return "flat"

    def _get_profitability_context_snapshot(
        self,
        asset: str,
        *,
        trade_side: str,
        expected_net_alpha_bps: Optional[float] = None,
        agent_signals: Optional[Dict[str, Any]] = None,
        market_data: Optional[Dict[str, Any]] = None,
    ) -> Dict[str, Any]:
        side_key = str(trade_side or "flat").lower()
        side_stats = (
            self._ensure_realized_pnl_breakdown()
            .get("by_side", {})
            .get(side_key, {})
            or {}
        )
        side_count = int(side_stats.get("count", 0) or 0)
        side_total_pnl_usd = float(side_stats.get("total_pnl_usd", 0.0) or 0.0)
        side_avg_pnl_bps_raw = side_stats.get("avg_pnl_bps")
        side_avg_pnl_bps = (
            float(side_avg_pnl_bps_raw)
            if side_avg_pnl_bps_raw is not None
            else None
        )

        fill_metrics = {}
        if getattr(self, "_fill_slope_monitor", None) is not None:
            try:
                fill_metrics = self._fill_slope_monitor.get_asset_fill_metrics(asset) or {}
            except Exception:
                fill_metrics = {}
        toxicity_rate = float(fill_metrics.get("toxicity_rate", 0.0) or 0.0)
        adverse_selection_proxy = float(fill_metrics.get("adverse_selection_proxy", 0.0) or 0.0)
        latest_slippage_bps = float(fill_metrics.get("latest_slippage_bps", 0.0) or 0.0)
        crowd = {}
        if isinstance(market_data, dict):
            crowd = dict(market_data.get("crowd", {}) or {})
        crowding_bias = float(crowd.get("crowding_bias", 0.0) or 0.0)
        panic_score = float(crowd.get("panic_score", 0.0) or 0.0)
        extreme_crowding = bool(crowd.get("extreme_crowding", False))
        if side_key == "long":
            crowding_alignment_score = -crowding_bias
        elif side_key == "short":
            crowding_alignment_score = crowding_bias
        else:
            crowding_alignment_score = 0.0
        toxicity_score = max(
            0.0,
            min(
                1.0,
                max(
                    toxicity_rate,
                    adverse_selection_proxy,
                ),
            ),
        )
        asset_key = str(asset or "").upper().replace("/USD", "").replace("USD", "")
        exit_alpha_review = self._get_exit_alpha_review_summary()
        asset_exit_alpha = dict(
            ((exit_alpha_review.get("by_asset", {}) or {}).get(asset_key, {}) or {})
        )
        exit_avg_retention_pct = asset_exit_alpha.get("avg_retention_pct")
        exit_avg_peak_to_exit_bps = asset_exit_alpha.get("avg_peak_to_exit_bps")

        if expected_net_alpha_bps is None:
            agent_signals = agent_signals or {}
            market_data = market_data or {}
            quant_direction = float(agent_signals.get("quant_direction", 0.0) or 0.0)
            quant_confidence = float(agent_signals.get("quant_confidence", 0.5) or 0.5)
            regime_confidence = float(agent_signals.get("regime_confidence", 0.5) or 0.5)
            effective_confidence = 0.7 * quant_confidence + 0.3 * regime_confidence
            alpha_proxy_bps = abs(quant_direction) * 200.0 * effective_confidence * 0.75
            fee_context = market_data.get("fee_context") if isinstance(market_data, dict) else None
            fee_bps = self._get_effective_fee_bps(
                fee_context,
                is_maker=False,
                default_bps=26.0,
            )
            try:
                friction = getattr(self.engine.guarantees.alpha_calculator, "FRICTION", None)
            except Exception:
                friction = None
            if friction is not None and hasattr(friction, "ASSET_SPREAD_BPS"):
                slippage_bps = float((friction.ASSET_SPREAD_BPS or {}).get(asset_key, market_data.get("spread_bps", 5.0) or 5.0))
                latency_bps = float(getattr(friction, "latency_cost_bps", 2.0) or 2.0)
                margin_bps = float(getattr(friction, "_margin_cost_bps", 0.0) or 0.0)
            else:
                slippage_bps = float(market_data.get("spread_bps", 5.0) or 5.0)
                latency_bps = 2.0
                margin_bps = 0.0
            expected_net_alpha_bps = alpha_proxy_bps - (fee_bps + slippage_bps + latency_bps + margin_bps)

        return {
            "side": side_key,
            "expected_net_alpha_bps": float(expected_net_alpha_bps or 0.0),
            "toxicity_score": float(toxicity_score),
            "toxicity_rate": toxicity_rate,
            "adverse_selection_proxy": adverse_selection_proxy,
            "latest_slippage_bps": latest_slippage_bps,
            "side_closed_trades": side_count,
            "side_total_realized_pnl_usd": side_total_pnl_usd,
            "side_avg_realized_pnl_bps": side_avg_pnl_bps,
            "crowding_bias": crowding_bias,
            "crowding_alignment_score": float(crowding_alignment_score),
            "panic_score": panic_score,
            "extreme_crowding": bool(extreme_crowding),
            "exit_avg_retention_pct": (
                float(exit_avg_retention_pct)
                if exit_avg_retention_pct is not None
                else None
            ),
            "exit_avg_peak_to_exit_bps": (
                float(exit_avg_peak_to_exit_bps)
                if exit_avg_peak_to_exit_bps is not None
                else None
            ),
        }

    @staticmethod
    def _intent_uses_maker_fee(intent: Any) -> bool:
        if bool(getattr(intent, "prefer_limit_order", False)):
            return True
        exec_mode = getattr(intent, "execution_mode", None)
        exec_mode_value = (
            exec_mode.value if hasattr(exec_mode, "value") else str(exec_mode or "")
        ).upper()
        return exec_mode_value in {"PASSIVE", "HIDDEN", "TWAP"}

    def _get_runtime_fee_friction_snapshot(
        self,
        *,
        intent: Any,
        market_data: Optional[Dict[str, Any]],
        alpha_result: Any,
    ) -> Dict[str, Any]:
        fee_context = market_data.get("fee_context") if isinstance(market_data, dict) else None
        alpha_fee_bps = float(getattr(alpha_result, "friction_fee_bps", 0.0) or 0.0) if alpha_result else 0.0
        slippage_bps = float(getattr(alpha_result, "friction_slippage_bps", 0.0) or 0.0) if alpha_result else 0.0
        latency_bps = float(getattr(alpha_result, "friction_latency_bps", 0.0) or 0.0) if alpha_result else 0.0
        margin_bps = float(getattr(alpha_result, "friction_margin_bps", 0.0) or 0.0) if alpha_result else 0.0
        # Use alpha_result's fee if available; otherwise use FRICTION's current value (not hardcoded 26)
        _fallback_fee = alpha_fee_bps
        if _fallback_fee <= 0.0:
            try:
                _fr = self.engine.guarantees.alpha_calculator.FRICTION
                _fallback_fee = _fr.maker_fee_bps if self._intent_uses_maker_fee(intent) else _fr.taker_fee_bps
            except Exception:
                _fallback_fee = 0.0
        runtime_fee_bps = self._get_effective_fee_bps(
            fee_context,
            is_maker=self._intent_uses_maker_fee(intent),
            default_bps=_fallback_fee,
        )
        # When alpha-gate logging already consumed the runtime fee model but the dataclass
        # still carries a stale zero, export the effective fee to keep the dashboard truthful.
        if alpha_fee_bps <= 0.0 and runtime_fee_bps > 0.0:
            alpha_fee_bps = float(runtime_fee_bps)
        return {
            "friction_fee_bps": float(runtime_fee_bps),
            "friction_fee_bps_alpha_gate": alpha_fee_bps,
            "friction_slippage_bps": slippage_bps,
            "friction_latency_bps": latency_bps,
            "friction_margin_bps": margin_bps,
            "friction_total_bps": float(runtime_fee_bps + slippage_bps + latency_bps + margin_bps),
            "friction_fee_source": str((fee_context or {}).get("fee_source", "alpha_gate_or_default")),
            "friction_maker_fee_bps": float((fee_context or {}).get("maker_fee_bps", 0.0) or 0.0),
            "friction_taker_fee_bps": float((fee_context or {}).get("taker_fee_bps", 0.0) or 0.0),
            "friction_fee_weight": float((fee_context or {}).get("fee_weight", 0.0) or 0.0),
            "friction_monthly_volume_usd": float((fee_context or {}).get("monthly_volume_usd", 0.0) or 0.0),
            "friction_in_free_tier": bool((fee_context or {}).get("in_free_tier", False)),
        }

    def _get_execution_session_fill_summary(self) -> Dict[str, Any]:
        assets = set(self._step15_candidate_assets())
        runtime_state = getattr(self, "_dashboard_asset_runtime", {}) or {}
        runtime_counts = {}
        for asset, raw in runtime_state.items():
            if not isinstance(raw, dict):
                continue
            assets.add(asset)
            runtime_counts[asset] = int(raw.get("session_fill_count", 0) or 0)

        ledger_counts = {}
        ledger_total = 0
        try:
            shadow_ledger = getattr(getattr(self, "p0_integrator", None), "shadow_ledger", None)
            if shadow_ledger and hasattr(shadow_ledger, "get_session_fill_summary"):
                _shadow_summary = shadow_ledger.get_session_fill_summary() or {}
                ledger_counts = dict(_shadow_summary.get("counts_by_asset", {}) or {})
                ledger_total = int(_shadow_summary.get("count", 0) or 0)
                assets.update(ledger_counts.keys())
        except Exception:
            ledger_counts = {}
            ledger_total = 0

        counts_by_asset = {}
        for asset in assets:
            counts_by_asset[asset] = max(
                int(runtime_counts.get(asset, 0) or 0),
                int(ledger_counts.get(asset, 0) or 0),
            )

        return {
            "count": max(sum(counts_by_asset.values()), ledger_total),
            "counts_by_asset": counts_by_asset,
        }

    def _get_shadow_ledger_window_fill_summary(self, *, hours: int) -> Dict[str, Any]:
        """Return rolling fill counts from shadow ledger disk state."""
        empty = {
            "count": 0,
            "counts_by_asset": {},
            "last_fill_at": None,
            "last_fill_at_by_asset": {},
        }
        if hours <= 0:
            return dict(empty)

        try:
            shadow_ledger = getattr(getattr(self, "p0_integrator", None), "shadow_ledger", None)
            ledger_dir = getattr(shadow_ledger, "output_dir", None) or (DATA_DIR / "shadow_ledger")
            if shadow_ledger and hasattr(shadow_ledger, "flush"):
                try:
                    shadow_ledger.flush()
                except Exception:
                    pass
            from defense.shadow_ledger_jsonl import ShadowLedgerReader

            reader = ShadowLedgerReader(str(ledger_dir))
            end_dt = datetime.now(timezone.utc)
            start_dt = end_dt - timedelta(hours=int(hours))
            summary = reader.summarize_fills_since(start_dt, end_dt=end_dt) or {}
            return {
                "count": int(summary.get("count", 0) or 0),
                "counts_by_asset": dict(summary.get("counts_by_asset", {}) or {}),
                "last_fill_at": summary.get("last_fill_at"),
                "last_fill_at_by_asset": dict(summary.get("last_fill_at_by_asset", {}) or {}),
            }
        except Exception:
            return dict(empty)

    def _resolve_execution_trade_side(self, asset: str, intent: Any) -> str:
        old_pos = getattr(self, "_paper_positions", {}).get(asset, {}) or {}
        direction = float(old_pos.get("direction", 0.0) or 0.0)
        if abs(direction) < 1e-9:
            direction = float(getattr(intent, "direction", 0.0) or 0.0)
        if direction > 0:
            return "long"
        if direction < 0:
            return "short"
        return "flat"

    def _get_execution_advisory_guard(self, asset: str, trade_side: str) -> Dict[str, Any]:
        guard_cfg = self._get_execution_advisory_config_snapshot()
        fill_summary = self._get_execution_session_fill_summary()
        fill_metrics = {}
        if self._fill_slope_monitor is not None:
            try:
                fill_metrics = self._fill_slope_monitor.get_asset_fill_metrics(asset) or {}
            except Exception:
                fill_metrics = {}

        side_stats = (
            self._ensure_realized_pnl_breakdown()
            .get("by_side", {})
            .get(str(trade_side or "flat").lower(), {})
            or {}
        )
        return evaluate_execution_advisory_guard(
            guard_cfg=guard_cfg,
            asset=asset,
            trade_side=trade_side,
            fill_summary=fill_summary,
            fill_metrics=fill_metrics,
            side_stats=side_stats,
        )

    def _record_step15_wavelet(self, asset: str, market_data: Dict[str, Any]) -> None:
        stats = getattr(self, "_step15_wavelet_stats", None)
        if not isinstance(stats, dict):
            return

        stats["ticks"] = int(stats.get("ticks", 0) or 0) + 1
        by_asset = stats.setdefault("by_asset", {})
        asset_stats = by_asset.setdefault(
            asset,
            {
                "ticks": 0,
                "any_nonzero_ticks": 0,
                "all_nonzero_ticks": 0,
                "changed_ticks": 0,
                "features": {
                    feature: {"nonzero_count": 0, "min": None, "max": None, "last": None}
                    for feature in self._STEP15_WAVELET_FEATURES
                },
            },
        )
        asset_stats["ticks"] = int(asset_stats.get("ticks", 0) or 0) + 1

        nonzero_count = 0
        any_changed = False
        feature_values = {}
        feature_state = asset_stats.setdefault("features", {})
        for feature in self._STEP15_WAVELET_FEATURES:
            try:
                value = float(market_data.get(feature, 0.0) or 0.0)
            except Exception:
                value = 0.0
            feature_values[feature] = value
            fstats = feature_state.setdefault(
                feature,
                {"nonzero_count": 0, "min": None, "max": None, "last": None},
            )
            if abs(value) > 1e-8:
                fstats["nonzero_count"] = int(fstats.get("nonzero_count", 0) or 0) + 1
                nonzero_count += 1
            if fstats.get("min") is None or value < float(fstats.get("min")):
                fstats["min"] = value
            if fstats.get("max") is None or value > float(fstats.get("max")):
                fstats["max"] = value
            prev = fstats.get("last")
            if prev is not None and abs(value - float(prev)) > 1e-12:
                any_changed = True
            fstats["last"] = value

        if nonzero_count > 0:
            asset_stats["any_nonzero_ticks"] = int(asset_stats.get("any_nonzero_ticks", 0) or 0) + 1
        if nonzero_count == len(self._STEP15_WAVELET_FEATURES):
            asset_stats["all_nonzero_ticks"] = int(asset_stats.get("all_nonzero_ticks", 0) or 0) + 1
        if any_changed:
            asset_stats["changed_ticks"] = int(asset_stats.get("changed_ticks", 0) or 0) + 1

        self._dashboard_asset_runtime.setdefault(asset, {}).update(
            {
                "wavelet_nonzero_count": nonzero_count,
                "wavelet_all_nonzero": nonzero_count == len(self._STEP15_WAVELET_FEATURES),
                "wavelet_changed": any_changed,
                "wavelet_feature_values": feature_values,
            }
        )

    def _get_step15_observation_contract(self) -> Dict[str, Any]:
        feature_dim = 122
        try:
            if getattr(self, "_obs_builder", None) is not None:
                feature_dim = int(len(self._obs_builder.feature_cols) or feature_dim)
        except Exception:
            pass

        env_dim = 4
        single_obs_dim = feature_dim + env_dim
        stack_depth = 8
        try:
            from drl.ensemble import N_STACK as _TQC_STACK

            stack_depth = int(_TQC_STACK or stack_depth)
        except Exception:
            pass

        return {
            "feature_dim": feature_dim,
            "env_dim": env_dim,
            "single_obs_dim": single_obs_dim,
            "runtime_input_shape": [single_obs_dim],
            "stack_depth": stack_depth,
            "effective_stacked_dim": single_obs_dim * stack_depth,
            "effective_stacked_shape": [single_obs_dim * stack_depth],
            "runtime_stack_owner": "TQCInference",
            "stacking_mode": "internal_runtime_buffer",
            "acceptance_note": "Runtime logs emit a single 126-dim obs; TQCInference stacks 8 frames internally to 1008.",
        }

    def _get_step15_wavelet_summary(self) -> Dict[str, Any]:
        stats = getattr(self, "_step15_wavelet_stats", {}) or {}
        by_asset = stats.get("by_asset", {}) or {}
        observed_assets = []
        asset_summary = {}
        all_assets_meet = True

        for asset, raw_asset_stats in by_asset.items():
            ticks = int(raw_asset_stats.get("ticks", 0) or 0)
            if ticks <= 0:
                continue
            observed_assets.append(asset)
            raw_features = raw_asset_stats.get("features", {}) or {}
            feature_summary = {}
            asset_nonzero = True
            asset_changing = True
            for feature in self._STEP15_WAVELET_FEATURES:
                raw_feature = raw_features.get(feature, {}) or {}
                nonzero_count = int(raw_feature.get("nonzero_count", 0) or 0)
                min_value = raw_feature.get("min")
                max_value = raw_feature.get("max")
                changing = (
                    min_value is not None
                    and max_value is not None
                    and abs(float(max_value) - float(min_value)) > 1e-12
                )
                feature_summary[feature] = {
                    "nonzero_count": nonzero_count,
                    "min": min_value,
                    "max": max_value,
                    "last": raw_feature.get("last"),
                    "nonzero_observed": nonzero_count > 0,
                    "changing_observed": changing,
                }
                asset_nonzero = asset_nonzero and nonzero_count > 0
                asset_changing = asset_changing and changing

            asset_summary[asset] = {
                "ticks": ticks,
                "any_nonzero_ticks": int(raw_asset_stats.get("any_nonzero_ticks", 0) or 0),
                "all_nonzero_ticks": int(raw_asset_stats.get("all_nonzero_ticks", 0) or 0),
                "changed_ticks": int(raw_asset_stats.get("changed_ticks", 0) or 0),
                "meets_nonzero_evidence": asset_nonzero,
                "meets_changing_evidence": asset_changing,
                "features": feature_summary,
            }
            all_assets_meet = all_assets_meet and asset_nonzero and asset_changing

        return {
            "feature_names": list(self._STEP15_WAVELET_FEATURES),
            "feature_count": len(self._STEP15_WAVELET_FEATURES),
            "ticks": int(stats.get("ticks", 0) or 0),
            "observed_asset_count": len(observed_assets),
            "observed_assets": sorted(observed_assets),
            "meets_nonzero_and_changing_evidence": bool(observed_assets) and all_assets_meet,
            "by_asset": asset_summary,
        }

    def _step15_candidate_assets(self, asset_data: Optional[Dict[str, Dict[str, Any]]] = None) -> List[str]:
        assets = set()
        config_assets = getattr(getattr(self, "config", None), "assets", None)
        if config_assets:
            assets.update(config_assets)
        assets.update(getattr(self, "_dashboard_asset_runtime", {}).keys())
        assets.update(getattr(self, "_dashboard_asset_snapshot", {}).keys())
        if asset_data:
            assets.update(asset_data.keys())
        return sorted(a for a in assets if a)

    def _parse_step15_timestamp(self, value: Any) -> Optional[datetime]:
        if not isinstance(value, str) or not value.strip():
            return None
        try:
            normalized = value.strip().replace(" ", "T")
            if normalized.endswith("Z") and ("+" in normalized[10:] or normalized[10:].count("-") >= 1):
                normalized = normalized[:-1]
            else:
                normalized = normalized.replace("Z", "+00:00")
            parsed = datetime.fromisoformat(normalized)
            if parsed.tzinfo is None:
                parsed = parsed.replace(tzinfo=timezone.utc)
            return parsed.astimezone(timezone.utc)
        except Exception:
            return None

    def _load_step15_run_started_at(self) -> Optional[datetime]:
        pid_file = getattr(self, "_PAPER_RUN_PID_FILE", self._PAPER_RUN_PID_FILE)
        try:
            if pid_file.exists():
                payload = json.loads(pid_file.read_text(encoding="utf-8"))
                started_at = self._parse_step15_timestamp(payload.get("started_at"))
                if started_at is not None:
                    return started_at
        except Exception:
            pass
        return None

    def _load_kill_switch_test_record(self) -> Dict[str, Any]:
        record_file = getattr(self, "_KILL_SWITCH_TEST_FILE", self._KILL_SWITCH_TEST_FILE)
        try:
            if record_file.exists():
                payload = json.loads(record_file.read_text(encoding="utf-8-sig"))
                if isinstance(payload, dict):
                    for key in ("source", "reason", "mode"):
                        if isinstance(payload.get(key), str):
                            payload[key] = payload[key].lstrip("\ufeff")
                    return payload
        except Exception:
            pass
        return {}

    def _write_kill_switch_test_record(self, source: str, reason: str) -> None:
        record_file = getattr(self, "_KILL_SWITCH_TEST_FILE", self._KILL_SWITCH_TEST_FILE)
        payload = {
            "triggered_at": datetime.now(timezone.utc).isoformat().replace("+00:00", "Z"),
            "source": str(source or "").lstrip("\ufeff"),
            "reason": str(reason or "").lstrip("\ufeff"),
            "mode": getattr(getattr(self, "config", None), "mode", "UNKNOWN").value
            if hasattr(getattr(getattr(self, "config", None), "mode", None), "value")
            else str(getattr(getattr(self, "config", None), "mode", "UNKNOWN")).lstrip("\ufeff"),
        }
        try:
            record_file.parent.mkdir(parents=True, exist_ok=True)
            tmp = record_file.with_suffix(".tmp")
            with open(tmp, "w", encoding="utf-8") as handle:
                handle.write(json.dumps(payload, indent=2, default=str))
                handle.flush()
                os.fsync(handle.fileno())
            tmp.replace(record_file)
        except Exception as exc:
            logger.debug(f"[STEP15] Kill-switch record write failed: {exc}")

    def _export_step15_status(
        self,
        round_count: int,
        tick_count: int,
        asset_data: Dict[str, Dict[str, Any]],
        active_positions: Dict[str, Dict[str, Any]],
        runtime_ts: str,
    ) -> None:
        try:
            assets = self._step15_candidate_assets(asset_data)
            runtime_state = getattr(self, "_dashboard_asset_runtime", {})
            shadow_fill_summary = {}
            try:
                shadow_ledger = getattr(getattr(self, "p0_integrator", None), "shadow_ledger", None)
                if shadow_ledger and hasattr(shadow_ledger, "get_session_fill_summary"):
                    shadow_fill_summary = shadow_ledger.get_session_fill_summary() or {}
            except Exception:
                shadow_fill_summary = {}

            ledger_fills_by_asset = dict(shadow_fill_summary.get("counts_by_asset", {}) or {})
            fills_by_asset = {}
            for asset in assets:
                runtime_fill_count = int(runtime_state.get(asset, {}).get("session_fill_count", 0) or 0)
                ledger_fill_count = int(ledger_fills_by_asset.get(asset, 0) or 0)
                fill_count = max(runtime_fill_count, ledger_fill_count)
                if fill_count > 0:
                    fills_by_asset[asset] = fill_count
            total_fills = max(
                sum(fills_by_asset.values()),
                int(shadow_fill_summary.get("count", 0) or 0),
            )
            rolling_24h_summary = self._get_shadow_ledger_window_fill_summary(hours=24)
            rolling_48h_summary = self._get_shadow_ledger_window_fill_summary(hours=48)

            def _build_fill_window_snapshot(raw_summary: Dict[str, Any], *, threshold: int) -> Dict[str, Any]:
                counts = {
                    str(asset): int(count or 0)
                    for asset, count in dict(raw_summary.get("counts_by_asset", {}) or {}).items()
                    if int(count or 0) > 0
                }
                total = int(raw_summary.get("count", 0) or 0)
                return {
                    "count": total,
                    "fills_by_asset": counts,
                    "assets_with_fills": sorted(counts.keys()),
                    "last_fill_at": raw_summary.get("last_fill_at"),
                    "last_fill_at_by_asset": dict(raw_summary.get("last_fill_at_by_asset", {}) or {}),
                    f"meets_{threshold}plus_threshold": total >= threshold,
                }

            session_fill_snapshot = {
                "count": total_fills,
                "fills_by_asset": fills_by_asset,
                "assets_with_fills": sorted(fills_by_asset.keys()),
                "last_fill_at": shadow_fill_summary.get("last_fill_at"),
                "last_fill_at_by_asset": dict(shadow_fill_summary.get("last_fill_at_by_asset", {}) or {}),
                "meets_5plus_threshold": total_fills >= 5,
                "meets_10plus_threshold": total_fills >= 10,
            }
            rolling_24h_snapshot = _build_fill_window_snapshot(rolling_24h_summary, threshold=5)
            rolling_48h_snapshot = _build_fill_window_snapshot(rolling_48h_summary, threshold=10)

            alpha_stats = getattr(self, "_step15_alpha_gate_stats", {}) or {}
            alpha_total = int(alpha_stats.get("total", 0) or 0)
            alpha_passed = int(alpha_stats.get("passed", 0) or 0)
            alpha_ratio = (alpha_passed / alpha_total) if alpha_total > 0 else None

            ood_stats = getattr(self, "_step15_ood_stats", {}) or {}
            ood_decisions = int(ood_stats.get("decisions", 0) or 0)
            ood_soft = int(ood_stats.get("soft_degrade", 0) or 0)
            ood_ratio = (ood_soft / ood_decisions) if ood_decisions > 0 else None

            started_at = self._load_step15_run_started_at()
            elapsed_hours = None
            if started_at is not None:
                elapsed_hours = max(
                    0.0,
                    (datetime.now(timezone.utc) - started_at).total_seconds() / 3600.0,
                )

            kill_record = self._load_kill_switch_test_record()
            kill_triggered_at = kill_record.get("triggered_at")
            kill_triggered_dt = self._parse_step15_timestamp(kill_triggered_at)
            observation_contract = self._get_step15_observation_contract()
            wavelet_summary = self._get_step15_wavelet_summary()
            realized_pnl_summary = self._get_realized_pnl_summary()
            execution_advisory = self._get_execution_advisory_config_snapshot()
            learned_execution_policy = self._get_learned_exec_runtime_snapshot()
            profit_calibration = self._get_profit_calibration_shadow()
            profit_calibration_live = self._get_profit_calibration_live_adjustments()
            exit_alpha_review = self._get_exit_alpha_review_summary()
            authority_states = self._get_runtime_authority_matrix(runtime_state)
            asset_status = build_step15_asset_status(
                assets=assets,
                asset_data=asset_data,
                runtime_state=runtime_state,
                active_positions=active_positions,
                asset_authorities=dict(authority_states.get("by_asset", {}) or {}),
            )

            status = {
                "updated_at": runtime_ts,
                "round": round_count,
                "tick_count": tick_count,
                "mode": getattr(getattr(self, "config", None), "mode", "PAPER").value
                if hasattr(getattr(getattr(self, "config", None), "mode", None), "value")
                else str(getattr(getattr(self, "config", None), "mode", "PAPER")),
                "risk_profile": getattr(getattr(self, "config", None), "risk_profile", "UNKNOWN"),
                "run": {
                    "started_at": started_at.isoformat().replace("+00:00", "Z") if started_at else None,
                    "elapsed_hours": elapsed_hours,
                    "meets_48h_minimum": bool(elapsed_hours is not None and elapsed_hours >= 48.0),
                },
                "crashes": {
                    "tick_fatal_count": int(getattr(self, "_tick_crash_count", 0) or 0),
                    "consecutive_by_asset": dict(getattr(self, "_consecutive_crashes", {}) or {}),
                },
                "fills": {
                    **session_fill_snapshot,
                    "scope": "session",
                    "session": session_fill_snapshot,
                    "rolling_24h": rolling_24h_snapshot,
                    "rolling_48h": rolling_48h_snapshot,
                },
                "positions": {
                    "count": len(active_positions),
                    "assets_with_positions": sorted(active_positions.keys()),
                    "three_assets_trading": len(rolling_48h_snapshot.get("fills_by_asset", {}) or {}) >= 3,
                    "three_assets_trading_session": len(fills_by_asset) >= 3,
                    "three_assets_trading_48h": len(rolling_48h_snapshot.get("fills_by_asset", {}) or {}) >= 3,
                },
                "alpha_gate": {
                    "passed": alpha_passed,
                    "total": alpha_total,
                    "pass_rate": alpha_ratio,
                    "meets_40pct_threshold": bool(alpha_ratio is not None and alpha_ratio > 0.40),
                    "by_asset": dict(alpha_stats.get("by_asset", {}) or {}),
                },
                "ood": {
                    "scored_decisions": ood_decisions,
                    "soft_degrade_count": ood_soft,
                    "soft_degrade_ratio": ood_ratio,
                    "hard_switch_count": int(ood_stats.get("hard_switch", 0) or 0),
                    "shadow_alert_count": int(ood_stats.get("shadow_alert", 0) or 0),
                    "meets_10pct_limit": bool(ood_ratio is not None and ood_ratio <= 0.10),
                    "by_asset": dict(ood_stats.get("by_asset", {}) or {}),
                },
                "realized_pnl": realized_pnl_summary,
                "execution_advisory": execution_advisory,
                "learned_execution_policy": learned_execution_policy,
                "profit_calibration": profit_calibration,
                "profit_calibration_live": profit_calibration_live,
                "exit_alpha_review": exit_alpha_review,
                "authority_states": authority_states,
                "observation": observation_contract,
                "wavelet": wavelet_summary,
                "kill_switch": {
                    "dead_man_available": bool(DEAD_MAN_SWITCH_AVAILABLE),
                    "dead_man_running": bool(getattr(self, "dead_man_switch", None)),
                    "manual_test_passed": bool(kill_triggered_dt is not None),
                    "last_manual_test_at": kill_triggered_at if kill_triggered_dt else None,
                    "last_manual_test_source": kill_record.get("source", ""),
                    "last_manual_test_reason": kill_record.get("reason", ""),
                },
                "assets": asset_status,
            }

            output_file = getattr(self, "_STEP15_STATUS_FILE", self._STEP15_STATUS_FILE)
            output_file.parent.mkdir(parents=True, exist_ok=True)
            tmp = output_file.with_suffix(".tmp")
            with open(tmp, "w", encoding="utf-8") as handle:
                handle.write(json.dumps(status, indent=2, default=str))
                handle.flush()
                os.fsync(handle.fileno())
            tmp.replace(output_file)
        except Exception as exc:
            logger.debug(f"[STEP15] Status export failed: {exc}")

    def _export_dashboard_state(self, round_count: int, tick_count: int, asset_data: dict):
        """Export current system state as JSON for the Streamlit dashboard."""
        try:
            asset_data = asset_data or {}
            merged_asset_data = {
                asset: dict(data) if isinstance(data, dict) else {}
                for asset, data in getattr(self, "_dashboard_asset_snapshot", {}).items()
            }
            for asset, data in asset_data.items():
                if isinstance(data, dict):
                    merged_asset_data[asset] = dict(data)
            self._dashboard_asset_snapshot = merged_asset_data

            active_positions = self._normalize_runtime_position_state(prune=True)
            equity = self.config.initial_capital  # FIX3: was hardcoded $100K
            if hasattr(self, 'account_sync') and self.account_sync:
                try:
                    equity = self.account_sync.get_equity()
                except Exception:
                    pass
            cumulative_pnl = 0.0
            if self.account_sync and self.account_sync.dry_run:
                cumulative_pnl = float(self.account_sync._dry_run_pnl or 0.0)
            _runtime_ts = datetime.now(timezone.utc).isoformat() + "Z"
            _drl_runtime = self._get_drl_runtime_snapshot()
            _realized_pnl_summary = self._get_realized_pnl_summary()
            _execution_advisory = self._get_execution_advisory_config_snapshot()
            _learned_exec_runtime = self._get_learned_exec_runtime_snapshot()
            _profit_calibration = self._get_profit_calibration_shadow()
            _profit_calibration_live = self._get_profit_calibration_live_adjustments()
            _exit_alpha_review = self._get_exit_alpha_review_summary()
            _authority_states = self._get_runtime_authority_matrix(merged_asset_data)
            merged_asset_data = inject_asset_authority_states(
                merged_asset_data,
                _authority_states,
            )
            _sent_assets = {
                asset: {
                    "source": data.get("llm_sentiment_source", "none"),
                    "headline_count": data.get("llm_headline_count", 0),
                    "source_status": data.get("llm_source_status", "unavailable"),
                    "tradeable_alpha": bool(data.get("llm_tradeable_alpha", False)),
                    "fallback_active": bool(data.get("llm_fallback_active", False)),
                }
                for asset, data in merged_asset_data.items()
            }

            state = {
                "updated_at": _runtime_ts,
                "round": round_count,
                "tick_count": tick_count,
                "equity": equity,
                "cumulative_pnl": cumulative_pnl,
                "peak_equity": getattr(self, "_peak_equity", equity),
                "mode": "PAPER",
                "risk_profile": self.config.risk_profile,
                "drl": _drl_runtime,
                "sentiment": {
                    "assets": _sent_assets,
                    "fallback_active": any(
                        item.get("fallback_active", False) for item in _sent_assets.values()
                    ),
                    "tradeable_assets": [
                        _asset for _asset, _item in _sent_assets.items()
                        if _item.get("tradeable_alpha", False)
                    ],
                },
                "realized_pnl": _realized_pnl_summary,
                "execution_advisory": _execution_advisory,
                "learned_execution_policy": _learned_exec_runtime,
                "profit_calibration": _profit_calibration,
                "profit_calibration_live": _profit_calibration_live,
                "exit_alpha_review": _exit_alpha_review,
                "authority_states": _authority_states,
                "assets": merged_asset_data,
                "positions": active_positions,
                "position_count": len(active_positions),
            }
            tmp = self._DASHBOARD_STATE_FILE.with_suffix(".tmp")
            # [FIX-40] fsync
            with open(tmp, 'w') as _f:
                _f.write(json.dumps(state, indent=2, default=str))
                _f.flush()
                os.fsync(_f.fileno())
            tmp.replace(self._DASHBOARD_STATE_FILE)
            self._export_step15_status(
                round_count=round_count,
                tick_count=tick_count,
                asset_data=merged_asset_data,
                active_positions=active_positions,
                runtime_ts=_runtime_ts,
            )
        except Exception as e:
            logger.debug(f"[DASHBOARD] State export failed: {e}")

