# CLI
# =============================================================================

def main():
    """Main CLI entrypoint."""
    
    # =========================================================================
    # CANONICAL ENTRYPOINT BANNER
    # =========================================================================
    print(f"""
================================================================================
    HMATS v{VERSION} - Hierarchical Multi-Agent Trading System
    Build: {BUILD_DATE}
    Mode: Production Ready
    
    --------------------------------------------------------------------------
    | CANONICAL_ENTRYPOINT = main.py                                         |
    | CANONICAL_CONFIG     = configs/cloud_production.json                   |
    | CANONICAL_SPINE      = core/runtime_spine.py                           |
    | CANONICAL_DECISION   = integration/integration_v36.py                  |
    --------------------------------------------------------------------------
================================================================================
""")

    # =========================================================================
    # PRINT SINGLE EXCHANGE BANNER
    # =========================================================================
    from exchange import print_exchange_banner
    # Banner auto-printed on import

    # =========================================================================
    # PRINT DRL AUTHORITY BANNER
    # =========================================================================
    if DRL_AUTHORITY_AVAILABLE:
        drl_gate = get_drl_authority_gate(DRLAuthorityLevel.SHADOW)
        drl_gate.print_banner()
    else:
        print("""
============================================================
[WARN] DRL_AUTHORITY_MODE=UNAVAILABLE
   DRL Authority Gate not loaded
============================================================
""")
    
    # =========================================================================
    # ACTIVATE RUNTIME MODE PROTECTION
    # =========================================================================
    try:
        from core.canonical_imports import activate_runtime_mode, get_sentiment_config
        activate_runtime_mode()
        logger.info("[MAIN] Runtime mode ACTIVATED - canonical imports enforced")
        
        # Log sentiment mode at startup
        sentiment_config = get_sentiment_config()
        sentiment_status = sentiment_config.get_status_string()
        can_trigger = sentiment_config.can_trigger_opportunity()
        logger.warning(
            f"[STARTUP] SENTIMENT_MODE={sentiment_status} "
            f"CAN_TRIGGER_OPPORTUNITY={can_trigger}"
        )
        print(f"    [STARTUP] SENTIMENT_MODE={sentiment_status}")
    except ImportError as e:
        logger.warning(f"[MAIN] canonical_imports not available: {e}")
    
    parser = argparse.ArgumentParser(
        description=f"HMATS v{VERSION} - Canonical Production Entrypoint",
        formatter_class=argparse.RawDescriptionHelpFormatter,
    )
    
    parser.add_argument(
        "--mode",
        choices=["verify", "paper", "backtest", "live"],
        default="verify",
        help="Run mode (default: verify)"
    )
    
    parser.add_argument(
        "--config",
        type=Path,
        default=Path("configs/cloud_production.json"),
        help="Config file path"
    )
    
    parser.add_argument(
        "--start",
        type=str,
        help="Backtest start date (YYYY-MM-DD)"
    )
    
    parser.add_argument(
        "--end",
        type=str,
        help="Backtest end date (YYYY-MM-DD)"
    )
    
    parser.add_argument(
        "--confirm-live",
        action="store_true",
        help="Confirm live trading (REQUIRED for --mode live)"
    )
    
    parser.add_argument(
        "--version",
        action="store_true",
        help="Show version and exit"
    )
    
    # P1-01: Risk profile overlay
    parser.add_argument(
        "--risk-profile",
        type=str,
        default=None,
        metavar="PROFILE",
        help="Risk profile name (e.g. ULTRA_AGGRESSIVE_5Y). Loads configs/<name>.json as overlay"
    )

    # TASK C (P1): Simulate disconnect for testing cancel-on-disconnect
    parser.add_argument(
        "--simulate-disconnect",
        type=int,
        default=0,
        metavar="N",
        help="Simulate disconnect after N ticks (verify/paper only, 0=disabled)"
    )
    
    args = parser.parse_args()
    
    if args.version:
        print(f"HMATS v{VERSION}")
        print(f"Build: {BUILD_DATE}")
        sys.exit(0)
    
    # Live mode safety check
    if args.mode == "live" and not args.confirm_live:
        print("ERROR: Live trading requires --confirm-live flag")
        print("This is a safety check to prevent accidental live trading.")
        sys.exit(1)
    
    # TASK C (P1): Validate simulate-disconnect is not used in live mode
    if args.simulate_disconnect > 0 and args.mode == "live":
        print("ERROR: --simulate-disconnect cannot be used in live mode")
        print("This is a safety feature for verify/paper testing only.")
        sys.exit(1)
    
    # Load config (with optional risk profile overlay)
    config = ProductionConfig.from_file(args.config, risk_profile=args.risk_profile)
    config.mode = RunMode(args.mode)
    config.backtest_start = args.start
    config.backtest_end = args.end
    config.simulate_disconnect_tick = args.simulate_disconnect  # TASK C
    
    # Create runner
    try:
        runner = HMATSProductionRunner(config)
    except Exception as e:
        logger.error(f"Failed to initialize: {e}")
        sys.exit(1)
    
    # Setup signal handlers
    def signal_handler(signum, frame):
        logger.info(f"Received signal {signum}")
        runner.stop()
    
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    
    # Run
    try:
        if args.mode == "verify":
            exit_code = asyncio.run(runner.run_verification())
            sys.exit(exit_code)
        elif args.mode == "paper":
            asyncio.run(runner.run_paper())
        elif args.mode == "backtest":
            if not args.start or not args.end:
                print("ERROR: Backtest requires --start and --end dates")
                sys.exit(1)
            results = asyncio.run(runner.run_backtest(args.start, args.end))
            print(f"Backtest results: {results}")
        elif args.mode == "live":
            asyncio.run(runner.run_live())
    except KeyboardInterrupt:
        logger.info("Interrupted")
    except Exception as e:
        logger.error(f"Runtime error: {e}")
        sys.exit(1)


if __name__ == "__main__":
    main()


